30	import org.springframework.http.HttpStatus;
31	import org.springframework.http.ResponseEntity;
32	import org.springframework.samples.petclinic.mapper.OwnerMapper;
33	import org.springframework.samples.petclinic.mapper.PetMapper;
34	import org.springframework.samples.petclinic.mapper.VisitMapper;
35	import org.springframework.samples.petclinic.model.Owner;
36	import org.springframework.samples.petclinic.model.Pet;
37	import org.springframework.samples.petclinic.model.Visit;
38	import org.springframework.samples.petclinic.rest.api.OwnersApi;
39	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
40	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.PetDto;
42	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
45	import org.springframework.samples.petclinic.service.ClinicService;
46	import org.springframework.security.access.prepost.PreAuthorize;
47	import org.springframework.web.bind.annotation.CrossOrigin;
48	import org.springframework.web.bind.annotation.RequestMapping;
49	import org.springframework.web.bind.annotation.RestController;
50	import org.springframework.web.util.UriComponentsBuilder;
51	
52	import jakarta.transaction.Transactional;
53	
54	/**
55	 * @author Vitaliy Fedoriv
56	 */
57	
58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    private final ClinicService clinicService;
64	
65	    private final OwnerMapper ownerMapper;
66	
67	    private final PetMapper petMapper;
68	
69	    private final VisitMapper visitMapper;
70	
71	    public OwnerRestControllerV1(ClinicService clinicService,
72	                                 OwnerMapper ownerMapper,
73	                                 PetMapper petMapper,
74	                                 VisitMapper visitMapper) {
75	        this.clinicService = clinicService;
76	        this.ownerMapper = ownerMapper;
77	        this.petMapper = petMapper;
78	        this.visitMapper = visitMapper;
79	    }
80	
81	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
82	    @Override
83	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
84	        Collection<Owner> owners;
85	        if (lastName != null) {
86	            owners = this.clinicService.findOwnerByLastName(lastName);
87	        } else {
88	            owners = this.clinicService.findAllOwners();
89	        }
90	        if (owners.isEmpty()) {
91	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
92	        }
93	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
94	    }
95	
96	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
97	    @Override
98	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
99	        Owner owner = this.clinicService.findOwnerById(ownerId);
100	        if (owner == null) {
101	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
102	        }
103	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
104	    }
105	
106	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
107	    @Override
108	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
109	        HttpHeaders headers = new HttpHeaders();
110	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
111	        String address = normalizeAddress(owner.getAddress());
112	        if (address.isEmpty()) {
113	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
114	        }
115	        owner.setAddress(address);
116	        String telephone = toE164(owner.getTelephone());
117	        if (telephone == null) {
118	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
119	        }
120	        if (owner.getEmail() != null) {
121	            String email = normalizeEmail(owner.getEmail());
122	            if (email == null) {
123	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
124	            }
125	            owner.setEmail(email);
126	        }
127	        LocalDate effectiveRegistrationDate = owner.getRegistrationDate();
128	        if (effectiveRegistrationDate == null) {
129	            effectiveRegistrationDate = LocalDate.now();
130	        }
131	        LocalDate registrationDate = toBusinessDay(effectiveRegistrationDate);
132	        owner.setRegistrationDate(registrationDate);
133	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
134	            return new ResponseEntity<>(HttpStatus.CONFLICT);
135	        }
136	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
137	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
138	        }
139	        for (Owner existing : this.clinicService.findAllOwners()) {
140	            if (telephone.equals(toE164(existing.getTelephone()))) {
141	                return new ResponseEntity<>(HttpStatus.CONFLICT);
142	            }
143	        }
144	        String lastNameKey = householdKey(owner.getLastName());
145	        String addressKey = householdKey(owner.getAddress());
146	        List<Owner> householdMembers = new ArrayList<>();
147	        for (Owner existing : this.clinicService.findAllOwners()) {
148	            if (lastNameKey.equals(householdKey(existing.getLastName()))
149	                && addressKey.equals(householdKey(existing.getAddress()))) {
150	                householdMembers.add(existing);
151	            }
152	        }
153	        if (!householdMembers.isEmpty()) {
154	            if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
155	                return new ResponseEntity<>(HttpStatus.CONFLICT);
156	            }
157	            String householdId = householdId(lastNameKey, addressKey);
158	            owner.setHouseholdId(householdId);
159	            for (Owner member : householdMembers) {
160	                if (!householdId.equals(member.getHouseholdId())) {
161	                    member.setHouseholdId(householdId);
162	                    this.clinicService.saveOwner(member);
163	                }
164	            }
165	        }
166	        owner.setTelephone(telephone);
167	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
168	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
169	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
170	        this.clinicService.saveOwner(owner);
171	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
172	        headers.setLocation(UriComponentsBuilder.newInstance()
173	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
174	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
175	    }
176	
177	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
178	    @Override
179	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
180	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
181	        if (currentOwner == null) {
182	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
183	        }
184	        currentOwner.setAddress(ownerFieldsDto.getAddress());
185	        currentOwner.setCity(ownerFieldsDto.getCity());
186	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
187	        currentOwner.setLastName(ownerFieldsDto.getLastName());
188	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
189	        this.clinicService.saveOwner(currentOwner);
190	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
191	    }
192	
193	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
194	    @Transactional
195	    @Override
196	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
197	        Owner owner = this.clinicService.findOwnerById(ownerId);
198	        if (owner == null) {
199	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
200	        }
201	        this.clinicService.deleteOwner(owner);
202	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
203	    }
204	
205	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
206	    @Override
207	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
208	        Owner owner = this.clinicService.findOwnerById(ownerId);
209	        if (owner == null) {
210	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
211	        }
212	        HttpHeaders headers = new HttpHeaders();
213	        Pet pet = petMapper.toPet(petFieldsDto);
214	        owner.setId(ownerId);
215	        pet.setOwner(owner);
216	        pet.getType().setName(null);
217	        this.clinicService.savePet(pet);
218	        PetDto petDto = petMapper.toPetDto(pet);
219	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
220	            .buildAndExpand(pet.getId()).toUri());
221	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
222	    }
223	
224	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
225	    @Override
226	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
227	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
228	        if (currentOwner != null) {
229	            Pet currentPet = this.clinicService.findPetById(petId);
230	            if (currentPet != null) {
231	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
232	                currentPet.setName(petFieldsDto.getName());
233	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
234	                this.clinicService.savePet(currentPet);
235	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
236	            }
237	        }
238	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
239	    }
240	
241	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
242	    @Override
243	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
244	        HttpHeaders headers = new HttpHeaders();
245	        Visit visit = visitMapper.toVisit(visitFieldsDto);
246	        Pet pet = new Pet();
247	        pet.setId(petId);
248	        visit.setPet(pet);
249	        this.clinicService.saveVisit(visit);
250	        VisitDto visitDto = visitMapper.toVisitDto(visit);
251	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
252	            .buildAndExpand(visit.getId()).toUri());
253	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
254	    }
255	
256	
257	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
258	    @Override
259	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
260	        Owner owner = this.clinicService.findOwnerById(ownerId);
261	        if (owner != null) {
262	            Pet pet = owner.getPet(petId);
263	            if (pet != null) {
264	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
265	            }
266	        }
267	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
268	    }
269	
270	    /**
271	     * The maximum number of owners permitted per city. Owner creation is rejected once the
272	     * owner's city already contains this many owners.
273	     */
274	    private static final int MAX_OWNERS_PER_CITY = 50;
275	
276	    /**
277	     * Counts how many existing owners live in the given city, compared case-insensitively.
278	     * This is evaluated before the new owner is persisted, so the owner being created is not
279	     * included in the count.
280	     *
281	     * @param city the new owner's city
282	     * @return the number of existing owners in that city
283	     */
284	    private int countOwnersInCity(String city) {
285	        int count = 0;
286	        for (Owner existing : this.clinicService.findAllOwners()) {
287	            if (city.equalsIgnoreCase(existing.getCity())) {
288	                count++;
289	            }
290	        }
291	        return count;
292	    }
293	
294	    /**
295	     * The maximum number of owners that may be created in a single business day. Owner
296	     * creation is rejected once this many owners already fall on the new owner's adjusted
297	     * business day {@code registrationDate}.
298	     */
299	    private static final int MAX_OWNERS_PER_DAY = 100;
300	
301	    /**
302	     * Rolls a date forward to the next business day: a Saturday or Sunday is moved forward
303	     * to the following Monday, while a weekday is returned unchanged.
304	     *
305	     * @param date the date to adjust
306	     * @return the same date if it is a weekday, otherwise the following Monday
307	     */
308	    private LocalDate toBusinessDay(LocalDate date) {
309	        DayOfWeek dayOfWeek = date.getDayOfWeek();
310	        if (dayOfWeek == DayOfWeek.SATURDAY) {
311	            return date.plusDays(2);
312	        }
313	        if (dayOfWeek == DayOfWeek.SUNDAY) {
314	            return date.plusDays(1);
315	        }
316	        return date;
317	    }
318	
319	    /**
320	     * Counts how many existing owners fall on the given business day, i.e. whose {@code
321	     * registrationDate} rolls forward to the same business day. This is evaluated before the
322	     * new owner is persisted, so the owner being created is not included in the count.
323	     *
324	     * @param businessDay the adjusted business day to count against
325	     * @return the number of existing owners registered on that business day
326	     */
327	    private int countOwnersRegisteredOn(LocalDate businessDay) {
328	        int count = 0;
329	        for (Owner existing : this.clinicService.findAllOwners()) {
330	            LocalDate existingDate = existing.getRegistrationDate();
331	            if (existingDate != null && businessDay.equals(toBusinessDay(existingDate))) {
332	                count++;
333	            }
334	        }
335	        return count;
336	    }
337	
338	    /**
339	     * Builds the customer code for a newly created owner, formatted
340	     * {@code '<CITY3>-<LAST3>-<NNNN>'} where {@code CITY3} is the upper-cased first
341	     * three letters of the city, {@code LAST3} the upper-cased first three letters of
342	     * the last name and {@code NNNN} is a per-city 4-digit zero-padded sequence equal
343	     * to one more than the number of owners already in that city.
344	     *
345	     * @param city     the owner's city
346	     * @param lastName the owner's last name
347	     * @return the assigned customer code (e.g. {@code 'SYD-SMI-0007'})
348	     */
349	    private String nextCustomerCode(String city, String lastName) {
350	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
351	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
352	        int sequence = 1;
353	        for (Owner existing : this.clinicService.findAllOwners()) {
354	            if (city.equalsIgnoreCase(existing.getCity())) {
355	                sequence++;
356	            }
357	        }
358	        return String.format("%s-%s-%04d", city3, last3, sequence);
359	    }
360	
361	    /**
362	     * Builds the membership number for a newly created owner, formatted
363	     * {@code '<customerCode>-M<YY>'} where {@code customerCode} is the owner's assigned
364	     * customer code and {@code YY} is the last two digits of the owner's registration
365	     * date year, zero-padded to two digits.
366	     *
367	     * @param customerCode     the owner's assigned customer code (e.g. {@code 'SYD-SMI-0007'})
368	     * @param registrationDate the owner's registration date
369	     * @return the assigned membership number (e.g. {@code 'SYD-SMI-0007-M26'})
370	     */
371	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
372	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
373	    }
374	
375	    /**
376	     * Counts how many existing owners share the given first and last name, compared
377	     * case-insensitively. This is evaluated before the new owner is persisted, so the
378	     * owner being created is not included in the count.
379	     *
380	     * @param firstName the new owner's first name
381	     * @param lastName  the new owner's last name
382	     * @return the number of existing owners with the same first and last name
383	     */
384	    private int countNamesakes(String firstName, String lastName) {
385	        int count = 0;
386	        for (Owner existing : this.clinicService.findAllOwners()) {
387	            if (firstName.equalsIgnoreCase(existing.getFirstName())
388	                && lastName.equalsIgnoreCase(existing.getLastName())) {
389	                count++;
390	            }
391	        }
392	        return count;
393	    }
394	
395	    /**
396	     * Canonical expansions applied to common street-type abbreviations during address
397	     * normalization. Keys and values are upper-cased so the lookup runs after the address
398	     * has itself been upper-cased.
399	     */
400	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
401	        "ST", "STREET",
402	        "RD", "ROAD",
403	        "AVE", "AVENUE");
404	
405	    /**
406	     * Normalizes an owner address for creation. Leading and trailing whitespace is trimmed,
407	     * every run of internal whitespace is collapsed to a single space, the result is
408	     * upper-cased and common street-type abbreviations are expanded ({@code ST -> STREET},
409	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). An abbreviation is recognized as a whole
410	     * token, optionally carrying a single trailing full stop (so both {@code 'St'} and
411	     * {@code 'St.'} become {@code 'STREET'}). The normalized value is what gets stored,
412	     * returned and compared for household duplicates; an address that is blank once
413	     * normalized fails the required-field check.
414	     *
415	     * @param address the raw address value supplied by the client
416	     * @return the normalized address (empty string when {@code address} is null or blank)
417	     */
418	    private static String normalizeAddress(String address) {
419	        if (address == null) {
420	            return "";
421	        }
422	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
423	        if (collapsed.isEmpty()) {
424	            return "";
425	        }
426	        StringBuilder normalized = new StringBuilder(collapsed.length());
427	        for (String token : collapsed.split(" ")) {
428	            String core = token.endsWith(".") ? token.substring(0, token.length() - 1) : token;
429	            String expanded = ADDRESS_ABBREVIATIONS.get(core);
430	            if (normalized.length() > 0) {
431	                normalized.append(' ');
432	            }
433	            normalized.append(expanded != null ? expanded : token);
434	        }
435	        return normalized.toString();
436	    }
437	
438	    /**
439	     * Normalizes a last name or address for household-duplicate comparison: leading and
440	     * trailing whitespace is trimmed, every run of internal whitespace is collapsed to a
441	     * single space and the result is lower-cased. Two owners are considered to share a
442	     * household when both their last names and addresses produce the same key.
443	     *
444	     * @param value the raw last name or address value
445	     * @return the normalized comparison key (empty string when {@code value} is null)
446	     */
447	    private static String householdKey(String value) {
448	        if (value == null) {
449	            return "";
450	        }
451	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
452	    }
453	
454	    /**
455	     * Derives the stable shared household identifier for the given normalized last name
456	     * and address keys. The identifier is deterministic — the same household (same
457	     * {@link #householdKey normalized} last name and address) always maps to the same
458	     * value — so every owner who joins a household is assigned an identical id. It is the
459	     * upper-cased first twelve hex characters of the SHA-256 digest of {@code
460	     * '<lastNameKey>|<addressKey>'}.
461	     *
462	     * @param lastNameKey the normalized last name key
463	     * @param addressKey  the normalized address key
464	     * @return the shared household identifier
465	     */
466	    private static String householdId(String lastNameKey, String addressKey) {
467	        String source = lastNameKey + "|" + addressKey;
468	        try {
469	            byte[] digest = MessageDigest.getInstance("SHA-256")
470	                .digest(source.getBytes(StandardCharsets.UTF_8));
471	            StringBuilder hex = new StringBuilder(digest.length * 2);
472	            for (byte b : digest) {
473	                hex.append(String.format("%02x", b));
474	            }
475	            return hex.substring(0, 12).toUpperCase();
476	        } catch (NoSuchAlgorithmException e) {
477	            throw new IllegalStateException("SHA-256 not available", e);
478	        }
479	    }
480	
481	    /**
482	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes
483	     * and brackets are stripped. When the number already carries a leading {@code '+'}
484	     * and country code these are kept; otherwise Australia's country code {@code '+61'}
485	     * is assumed and a single leading {@code '0'} is dropped from the national digits.
486	     * The resulting number must have between 8 and 15 digits after the {@code '+'}.
487	     *
488	     * @param telephone the raw telephone value supplied by the client
489	     * @return the E.164 telephone (e.g. {@code +61412345678}), or {@code null} when it
490	     *         cannot form a valid E.164 number (signalling a 400 Bad Request)
491	     */
492	    private static String toE164(String telephone) {
493	        if (telephone == null) {
494	            return null;
495	        }
496	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
497	        String digits;
498	        if (cleaned.startsWith("+")) {
499	            digits = cleaned.substring(1);
500	        } else {
501	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
502	            digits = "61" + national;
503	        }
504	        return digits.matches("[0-9]{8,15}") ? "+" + digits : null;
505	    }
506	
507	    /**
508	     * Normalizes an owner email for creation. A present email must be a syntactically
509	     * valid address; the returned value is lower-cased.
510	     *
511	     * @param email the raw email value supplied by the client (never {@code null} here)
512	     * @return the lower-cased email, or {@code null} when it is not a syntactically valid
513	     *         address (signalling a 400 Bad Request)
514	     */
515	    private static String normalizeEmail(String email) {
516	        String trimmed = email.trim();
517	        if (!trimmed.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$")) {
518	            return null;
519	        }
520	        return trimmed.toLowerCase();
521	    }
522	}
